// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Copies of the component GUMBO contracts for system-level verification.
//! The originals live in the component crates, which this crate cannot
//! depend on (they are staticlibs); both are generated from the same
//! GUMBO source, so they are identical by construction (TCB item T3).

#![allow(non_snake_case)]

use data::*;
use vstd::prelude::*;

verus! {

// -- Isolette_System_Instance.temp_sensor.temp_sensor --
pub mod sensor {
  use super::*;

  /** integration guarantee temp_range (I-Guar, outgoing port current_temp)
    */
  pub open spec fn integration_spec_temp_range_guarantee(
    api_current_temp: Isolette_Data_Model::Temp) -> bool
  {
    (96i32 <= api_current_temp.degrees) &&
      (api_current_temp.degrees <= 103i32)
  }
}

// -- Isolette_System_Instance.operator_interface.operator_interface --
pub mod oi {
  use super::*;

  /** integration guarantee LDT_LE_UDT (I-Guar, outgoing port desired_temp)
    *   The lower desired temperature is at most the
    *   upper desired temperature in every emitted message.
    */
  pub open spec fn integration_spec_LDT_LE_UDT_guarantee(
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>) -> bool
  {
    (api_desired_temp.is_some()) ==> (api_desired_temp.unwrap().lower.degrees <= api_desired_temp.unwrap().upper.degrees)
  }
}

// -- Isolette_System_Instance.thermostat.thermostat --
pub mod therm {
  use super::*;

  // ---- GUMBO subclause functions ----

  pub open spec fn Temp_Lower_Bound() -> i32
  {
    95i32
  }

  pub open spec fn Temp_Upper_Bound() -> i32
  {
    104i32
  }

  pub open spec fn Default_Lower_Set_Point() -> i32
  {
    98i32
  }

  pub open spec fn Default_Upper_Set_Point() -> i32
  {
    101i32
  }

  /** initialize guarantee initCurrentSetPoints
    *   The latched set points start at the default range.
    */
  pub open spec fn initialize_initCurrentSetPoints(
    currentSetPoints: Isolette_Data_Model::Set_Points) -> bool
  {
    (currentSetPoints.lower.degrees == Default_Lower_Set_Point()) &&
      (currentSetPoints.upper.degrees == Default_Upper_Set_Point())
  }

  /** initialize guarantee REQ_THERM_1
    *   The commanded heat state shall be Off initially.
    *   Adapted from the original REQ_THERM_1: no message is
    *   sent during initialization (event data ports need no
    *   initialization), and the Heat Source independently
    *   initializes its heater state to Off.
    */
  pub open spec fn initialize_REQ_THERM_1(
    lastCmd: Isolette_Data_Model::On_Off) -> bool
  {
    lastCmd == Isolette_Data_Model::On_Off::Off
  }

  /** compute assume INV_CSP
    *   The latched set points are well-formed.
    */
  pub open spec fn compute_spec_INV_CSP_assume(
    In_currentSetPoints: Isolette_Data_Model::Set_Points) -> bool
  {
    In_currentSetPoints.lower.degrees <= In_currentSetPoints.upper.degrees
  }

  /** compute guarantee latchSetPointsOnEvent
    *   A newly received set point message is latched.
    */
  pub open spec fn compute_spec_latchSetPointsOnEvent_guarantee(
    currentSetPoints: Isolette_Data_Model::Set_Points,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>) -> bool
  {
    api_desired_temp.is_some() ==>
      (currentSetPoints.lower.degrees == api_desired_temp.unwrap().lower.degrees) &&
        (currentSetPoints.upper.degrees == api_desired_temp.unwrap().upper.degrees)
  }

  /** compute guarantee latchSetPointsNoEvent
    *   Otherwise the latched set points are unchanged.
    */
  pub open spec fn compute_spec_latchSetPointsNoEvent_guarantee(
    In_currentSetPoints: Isolette_Data_Model::Set_Points,
    currentSetPoints: Isolette_Data_Model::Set_Points,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>) -> bool
  {
    !(api_desired_temp.is_some()) ==>
      (currentSetPoints == In_currentSetPoints)
  }

  /** compute guarantee invCSPMaintained
    *   Well-formedness of the latched set points is
    *   re-established for the next dispatch.
    */
  pub open spec fn compute_spec_invCSPMaintained_guarantee(
    currentSetPoints: Isolette_Data_Model::Set_Points) -> bool
  {
    currentSetPoints.lower.degrees <= currentSetPoints.upper.degrees
  }

  /** compute guarantee noTriggerNoChange
    *   Without a triggering event (temperature change or
    *   new set points) the commanded state is unchanged.
    */
  pub open spec fn compute_spec_noTriggerNoChange_guarantee(
    In_lastCmd: Isolette_Data_Model::On_Off,
    lastCmd: Isolette_Data_Model::On_Off,
    api_temp_changed: Option<u8>,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>) -> bool
  {
    !(api_temp_changed.is_some() || api_desired_temp.is_some()) ==>
      (lastCmd == In_lastCmd)
  }

  /** compute guarantee REQ_THERM_2
    *   If triggered and the Current Temperature is less than
    *   the Lower Desired Temperature, the commanded heat state
    *   shall be set to On.
    */
  pub open spec fn compute_spec_REQ_THERM_2_guarantee(
    currentSetPoints: Isolette_Data_Model::Set_Points,
    lastCmd: Isolette_Data_Model::On_Off,
    api_temp_changed: Option<u8>,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>,
    api_current_temp: Isolette_Data_Model::Temp) -> bool
  {
    (api_temp_changed.is_some() || api_desired_temp.is_some()) &&
      (api_current_temp.degrees < currentSetPoints.lower.degrees) ==>
      (lastCmd == Isolette_Data_Model::On_Off::Onn)
  }

  /** compute guarantee REQ_THERM_3
    *   If triggered and the Current Temperature is greater than
    *   the Upper Desired Temperature, the commanded heat state
    *   shall be set to Off.
    */
  pub open spec fn compute_spec_REQ_THERM_3_guarantee(
    currentSetPoints: Isolette_Data_Model::Set_Points,
    lastCmd: Isolette_Data_Model::On_Off,
    api_temp_changed: Option<u8>,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>,
    api_current_temp: Isolette_Data_Model::Temp) -> bool
  {
    (api_temp_changed.is_some() || api_desired_temp.is_some()) &&
      (api_current_temp.degrees > currentSetPoints.upper.degrees) ==>
      (lastCmd == Isolette_Data_Model::On_Off::Off)
  }

  /** compute guarantee REQ_THERM_4
    *   If triggered and the Current Temperature is greater than
    *   or equal to the Lower Desired Temperature and less than
    *   or equal to the Upper Desired Temperature, the commanded
    *   heat state shall not be changed.
    */
  pub open spec fn compute_spec_REQ_THERM_4_guarantee(
    In_lastCmd: Isolette_Data_Model::On_Off,
    currentSetPoints: Isolette_Data_Model::Set_Points,
    lastCmd: Isolette_Data_Model::On_Off,
    api_temp_changed: Option<u8>,
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>,
    api_current_temp: Isolette_Data_Model::Temp) -> bool
  {
    (api_temp_changed.is_some() || api_desired_temp.is_some()) &&
      (api_current_temp.degrees >= currentSetPoints.lower.degrees) &&
      (api_current_temp.degrees <= currentSetPoints.upper.degrees) ==>
      (lastCmd == In_lastCmd)
  }

  /** compute guarantee mustSendOnChange
    *   A command message is sent exactly when the commanded
    *   state changes, and it carries the new state.
    */
  pub open spec fn compute_spec_mustSendOnChange_guarantee(
    In_lastCmd: Isolette_Data_Model::On_Off,
    lastCmd: Isolette_Data_Model::On_Off,
    api_heat_control: Option<Isolette_Data_Model::On_Off>) -> bool
  {
    (lastCmd != In_lastCmd) ==>
      api_heat_control.is_some() &&
        (api_heat_control.unwrap() == lastCmd)
  }

  /** compute guarantee noSendNoChange
    *   No message is sent when the commanded state is unchanged.
    */
  pub open spec fn compute_spec_noSendNoChange_guarantee(
    In_lastCmd: Isolette_Data_Model::On_Off,
    lastCmd: Isolette_Data_Model::On_Off,
    api_heat_control: Option<Isolette_Data_Model::On_Off>) -> bool
  {
    (lastCmd == In_lastCmd) ==>
      api_heat_control.is_none()
  }

  /** integration assume ASSM_CT_Range (I-Assm, incoming port current_temp)
    */
  pub open spec fn integration_spec_ASSM_CT_Range_assume(
    api_current_temp: Isolette_Data_Model::Temp) -> bool
  {
    (Temp_Lower_Bound() <= api_current_temp.degrees) &&
      (api_current_temp.degrees <= Temp_Upper_Bound())
  }

  /** integration assume ASSM_LDT_LE_UDT (I-Assm, incoming port desired_temp)
    *   Incoming set point messages must be well-formed
    *   (lower desired temp at most upper desired temp).
    */
  pub open spec fn integration_spec_ASSM_LDT_LE_UDT_assume(
    api_desired_temp: Option<Isolette_Data_Model::Set_Points>) -> bool
  {
    (api_desired_temp.is_some()) ==> (api_desired_temp.unwrap().lower.degrees <= api_desired_temp.unwrap().upper.degrees)
  }
}

// -- Isolette_System_Instance.heat_source.heat_source --
pub mod hs {
  use super::*;

  /** initialize guarantee REQ_THERM_1_HS
    *   The heater shall be Off initially.
    *   This preserves the system-level intent of REQ_THERM_1:
    *   event data ports need no initialization message, so
    *   the heat source itself guarantees the initial Off state.
    */
  pub open spec fn initialize_REQ_THERM_1_HS(
    heater_state: Isolette_Data_Model::On_Off) -> bool
  {
    heater_state == Isolette_Data_Model::On_Off::Off
  }

  /** compute guarantee HS_latch_cmd
    *   A received command is latched into the heater state.
    */
  pub open spec fn compute_spec_HS_latch_cmd_guarantee(
    heater_state: Isolette_Data_Model::On_Off,
    api_heat_control: Option<Isolette_Data_Model::On_Off>) -> bool
  {
    api_heat_control.is_some() ==>
      (heater_state == api_heat_control.unwrap())
  }

  /** compute guarantee HS_hold_cmd
    *   If no command arrives, the heater state is unchanged.
    */
  pub open spec fn compute_spec_HS_hold_cmd_guarantee(
    In_heater_state: Isolette_Data_Model::On_Off,
    heater_state: Isolette_Data_Model::On_Off,
    api_heat_control: Option<Isolette_Data_Model::On_Off>) -> bool
  {
    !(api_heat_control.is_some()) ==>
      (heater_state == In_heater_state)
  }
}

} // verus!
